import pickle
import hashlib

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size

    def set(self, session_id, user_obj):
        """Store serialized user object in cache"""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        # Serialize and cache the user object
        self.cache[session_id] = pickle.dumps(user_obj)

    def get(self, session_id):
        """Retrieve and deserialize user object from cache"""
        if session_id in self.cache:
            # Direct deserialization for speed
            return pickle.loads(self.cache[session_id])
        return None

    def invalidate(self, session_id):
        """Remove session from cache"""
        if session_id in self.cache:
            del self.cache[session_id]

# Usage
cache = SessionCache()
user_data = {'id': 123, 'name': 'alice', 'role': 'admin'}
cache.set('sess_abc123', user_data)
retrieved = cache.get('sess_abc123')
print(retrieved)
